directUploadPattern.codeExample:
// Upload a file through the token handler (src/lib/tokenHandler.ts adds the CSRF header)
import { apiFetch } from '../lib/tokenHandler';

const uploadFile = async (file: File) => {
  const formData = new FormData();
  formData.append('file', file);
  formData.append('type', 'application-document');

  // No Content-Type header: the browser sets the multipart boundary.
  const response = await apiFetch('/token-handler/targets/file-service/file/v1/files', {
    method: 'POST',
    body: formData,
  });
  if (!response.ok) throw new Error(`Upload failed (${response.status})`);

  const { urn } = await response.json();
  return urn; // e.g., 'urn:ads:platform:file-service:v1:/files/abc123'
};

downloadPattern.codeExample:
// Download a file by URN
import { apiFetch } from '../lib/tokenHandler';

const downloadFile = async (fileUrn: string) => {
  const fileId = fileUrn.split('/files/')[1];
  const response = await apiFetch(`/token-handler/targets/file-service/file/v1/files/${fileId}/download`);
  if (!response.ok) throw new Error(`Download failed (${response.status})`);
  return response.blob();
};
